WHERE (toLower(church.name) CONTAINS 'church of the guanche people' OR any(alias IN coalesce(church.aliases, []) WHERE toLower(alias) CONTAINS 'church of the guanche people'))
  AND (toLower(laguna.name) CONTAINS 'san cristóbal de la laguna' OR any(alias IN coalesce(laguna.aliases, []) WHERE toLower(alias) CONTAINS 'san cristóbal de la laguna'))
  AND (toLower(tenerife.name) CONTAINS 'tenerife' OR any(alias IN coalesce(tenerife.aliases, []) WHERE toLower(alias) CONTAINS 'tenerife'))
  AND (toLower(canaries.name) CONTAINS 'canary islands' OR any(alias IN coalesce(canaries.aliases, []) WHERE toLower(alias) CONTAINS 'canary islands'))
  AND (toLower(macaronesia.name) CONTAINS 'macaronesia' OR any(alias IN coalesce(macaronesia.aliases, []) WHERE toLower(alias) CONTAINS 'macaronesia'))
MATCH p1=(church)-[*1..3]-(laguna)
MATCH p2=(laguna)-[*1..3]-(tenerife)
MATCH p3=(tenerife)-[*1..3]-(canaries)
MATCH p4=(canaries)-[*1..3]-(macaronesia)
RETURN church.name AS church, [r IN relationships(p1) | type(r)] AS church_laguna_relationships,
       laguna.name AS location, [r IN relationships(p2) | type(r)] AS laguna_tenerife_relationships,
       tenerife.name AS island, [r IN relationships(p3) | type(r)] AS tenerife_canary_islands_relationships,
       canaries.name AS larger_area, [r IN relationships(p4) | type(r)] AS canary_islands_macaronesia_relationships,
       macaronesia.name AS region
LIMIT 10
